using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public sealed class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    [TestClass]
    public sealed class FormatPhoneNumberTests
    {
        private readonly StringFormatter _formatter = new();

        [TestMethod]
        public void FormatsValidDigits()
        {
            var result = _formatter.FormatPhoneNumber("1234567890");

            Assert.AreEqual("(123) 456-7890", result);
        }

        [TestMethod]
        public void ResultStartsWithAreaCodeInParentheses()
        {
            var result = _formatter.FormatPhoneNumber("8005551234");

            Assert.StartsWith(result, "(800)");
        }

        [TestMethod]
        public void ResultEndsWithLastFourDigits()
        {
            var result = _formatter.FormatPhoneNumber("8005551234");

            Assert.EndsWith(result, "1234");
        }

        [TestMethod]
        public void ThrowsOnNull()
        {
            Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
        }

        [TestMethod]
        [DataRow("123")]
        [DataRow("12345678901")]
        [DataRow("")]
        public void ThrowsOnInvalidLength(string digits)
        {
            Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
        }
    }

    [TestClass]
    public sealed class BuildGreetingTests
    {
        private readonly StringFormatter _formatter = new();

        [TestMethod]
        public void BuildsGreetingWithDefaultTitle()
        {
            var result = _formatter.BuildGreeting("Smith");

            Assert.AreEqual("Dear Mr. Smith,", result);
        }

        [TestMethod]
        public void BuildsGreetingWithCustomTitle()
        {
            var result = _formatter.BuildGreeting("Johnson", "Dr.");

            Assert.AreEqual("Dear Dr. Johnson,", result);
        }

        [TestMethod]
        public void ResultStartsWithDear()
        {
            var result = _formatter.BuildGreeting("Doe", "Ms.");

            Assert.StartsWith(result, "Dear");
        }

        [TestMethod]
        public void ResultEndsWithComma()
        {
            var result = _formatter.BuildGreeting("Doe");

            Assert.EndsWith(result, ",");
        }

        [TestMethod]
        [DataRow(null)]
        [DataRow("")]
        [DataRow("   ")]
        public void ThrowsOnNullOrWhiteSpaceName(string? name)
        {
            Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting(name!));
        }
    }

    [TestClass]
    public sealed class GenerateSlugTests
    {
        private readonly StringFormatter _formatter = new();

        [TestMethod]
        [DataRow("Hello World", "hello-world")]
        [DataRow("  Foo Bar Baz  ", "foo-bar-baz")]
        [DataRow("C# is Great!", "c-is-great")]
        [DataRow("already-slugged", "already-slugged")]
        public void GeneratesExpectedSlug(string title, string expected)
        {
            var result = _formatter.GenerateSlug(title);

            Assert.AreEqual(expected, result);
        }

        [TestMethod]
        public void SlugDoesNotStartWithHyphen()
        {
            var result = _formatter.GenerateSlug("---Leading Hyphens");

            Assert.StartsWith(result, "l");
        }

        [TestMethod]
        public void SlugDoesNotEndWithHyphen()
        {
            var result = _formatter.GenerateSlug("Trailing Hyphens---");

            Assert.EndsWith(result, "s");
        }

        [TestMethod]
        [DataRow(null)]
        [DataRow("")]
        [DataRow("   ")]
        public void ThrowsOnNullOrWhiteSpaceTitle(string? title)
        {
            Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug(title!));
        }
    }

    [TestClass]
    public sealed class FormatCurrencyTests
    {
        private readonly StringFormatter _formatter = new();

        [TestMethod]
        public void FormatsWithDefaultDollarSign()
        {
            var result = _formatter.FormatCurrency(19.99m);

            Assert.AreEqual("$19.99", result);
        }

        [TestMethod]
        public void FormatsWithCustomSymbol()
        {
            var result = _formatter.FormatCurrency(100m, "€");

            Assert.AreEqual("€100.00", result);
        }

        [TestMethod]
        public void ResultStartsWithCurrencySymbol()
        {
            var result = _formatter.FormatCurrency(5.5m, "£");

            Assert.StartsWith(result, "£");
        }

        [TestMethod]
        public void ResultEndsWithTwoDecimalPlaces()
        {
            var result = _formatter.FormatCurrency(7m);

            Assert.EndsWith(result, ".00");
        }

        [TestMethod]
        public void FormatsNegativeAmount()
        {
            var result = _formatter.FormatCurrency(-42.5m);

            Assert.AreEqual("$-42.50", result);
        }

        [TestMethod]
        public void FormatsZero()
        {
            var result = _formatter.FormatCurrency(0m);

            Assert.AreEqual("$0.00", result);
        }
    }
}

